import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Guide d'utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/usage.md","filePath":"fr/guide/usage.md","lastUpdated":1793173149000}`),a={name:`fr/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="guide-d-utilisation" tabindex="-1">Guide d&#39;utilisation <a class="header-anchor" href="#guide-d-utilisation" aria-label="Permalink to “Guide d&#39;utilisation”">​</a></h1><h2 id="principes-de-base" tabindex="-1">Principes de base <a class="header-anchor" href="#principes-de-base" aria-label="Permalink to “Principes de base”">​</a></h2><h3 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to “Objectif”">​</a></h3><p>Remplissez une grille 9×9 de sorte que chaque <strong>ligne</strong>, chaque <strong>colonne</strong> et chacun des neuf <strong>blocs</strong> 3×3 contienne tous les chiffres de 1 à 9 exactement une fois. Aucune répétition n&#39;est autorisée dans une même unité.</p><h3 id="comment-jouer" tabindex="-1">Comment jouer <a class="header-anchor" href="#comment-jouer" aria-label="Permalink to “Comment jouer”">​</a></h3><ul><li><strong>Placer un chiffre</strong> : touchez ou cliquez sur une case vide, puis touchez un chiffre du pavé numérique en bas de l&#39;écran.</li><li><strong>Notes au crayon (candidats)</strong> : activez le mode Crayon, puis touchez les cases pour inscrire de petits chiffres candidats. Pratique pour suivre les possibilités.</li><li><strong>Effacer</strong> : touchez le bouton Effacer pour vider une case (ou effacer les notes au crayon lorsque le mode crayon est actif).</li><li><strong>Indice</strong> : touchez Indice pour révéler la valeur correcte d&#39;une case.</li><li><strong>Annuler</strong> : touchez Annuler pour revenir sur votre dernier coup (l&#39;historique d&#39;annulation est complet).</li></ul><h3 id="niveaux-de-difficulte" tabindex="-1">Niveaux de difficulté <a class="header-anchor" href="#niveaux-de-difficulte" aria-label="Permalink to “Niveaux de difficulté”">​</a></h3><p>Chaque niveau de difficulté détermine le nombre de cases préremplies au départ :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Cases préremplies</th><th>Idéal pour</th></tr></thead><tbody><tr><td>Facile</td><td>45</td><td>Débutants et parties rapides</td></tr><tr><td>Moyen</td><td>36</td><td>Joueurs occasionnels</td></tr><tr><td>Difficile</td><td>31</td><td>Solveurs réguliers</td></tr><tr><td>Expert</td><td>27</td><td>Joueurs expérimentés</td></tr><tr><td>Maître</td><td>24</td><td>Maîtres du puzzle</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Plateau de jeu Sudoku sur Mac"></p><h2 id="controles-du-jeu" tabindex="-1">Contrôles du jeu <a class="header-anchor" href="#controles-du-jeu" aria-label="Permalink to “Contrôles du jeu”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>Touchez</strong> une case vide pour la sélectionner</li><li><strong>Touchez un chiffre</strong> sur le pavé pour le placer</li><li><strong>Activez le mode Crayon</strong> pour saisir ou effacer des notes candidates</li><li><strong>Utilisez Effacer</strong> pour vider une case</li><li><strong>Utilisez Indice</strong> pour obtenir de l&#39;aide en cas de blocage</li><li><strong>Utilisez Annuler</strong> pour revenir en arrière</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>Cliquez avec le bouton gauche</strong> sur une case vide pour la sélectionner</li><li><strong>Appuyez sur une touche numérique (1–9)</strong> ou cliquez sur le pavé à l&#39;écran pour placer un chiffre</li><li><strong>Activez le mode Crayon</strong> pour les notes candidates</li><li><strong>Raccourcis clavier</strong> : <ul><li><code>⌘N</code> — Nouvelle partie</li><li><code>⌘Z</code> — Annuler</li><li><code>⌘1</code> à <code>⌘5</code> — Démarrer une nouvelle partie à chaque niveau de difficulté</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="Écran d&#39;accueil de Sudoku sur iPhone"></p><p><img src="/screenshot-ipad-main.png" alt="Écran d&#39;accueil de Sudoku sur iPad"></p><h2 id="fonctions-intelligentes" tabindex="-1">Fonctions intelligentes <a class="header-anchor" href="#fonctions-intelligentes" aria-label="Permalink to “Fonctions intelligentes”">​</a></h2><h3 id="systeme-de-notes-au-crayon" tabindex="-1">Système de notes au crayon <a class="header-anchor" href="#systeme-de-notes-au-crayon" aria-label="Permalink to “Système de notes au crayon”">​</a></h3><p>Lorsque vous activez le mode Crayon, vous pouvez inscrire de petits chiffres candidats dans les cases vides. Le système de notes intelligent :</p><ul><li><strong>Efface automatiquement les notes voisines</strong> : lorsque vous placez un chiffre définitif, les notes au crayon correspondant à ce chiffre sont retirées de toutes les cases de la même ligne, de la même colonne et du même bloc.</li><li><strong>Bascule case par case</strong> : passez du mode saisie au mode crayon à tout moment.</li></ul><h3 id="verification-des-erreurs" tabindex="-1">Vérification des erreurs <a class="header-anchor" href="#verification-des-erreurs" aria-label="Permalink to “Vérification des erreurs”">​</a></h3><p>La mise en évidence facultative des erreurs affiche en rouge les saisies incorrectes, ce qui vous aide à progresser sans dévoiler la solution.</p><h3 id="defi-quotidien" tabindex="-1">Défi quotidien <a class="header-anchor" href="#defi-quotidien" aria-label="Permalink to “Défi quotidien”">​</a></h3><p>Une nouvelle grille de niveau Maître est générée chaque jour. Votre progression dans le défi quotidien est suivie dans les statistiques, avec une vue calendrier affichant votre série.</p><h3 id="statistiques" tabindex="-1">Statistiques <a class="header-anchor" href="#statistiques" aria-label="Permalink to “Statistiques”">​</a></h3><p>Suivez votre parcours dans Sudoku :</p><ul><li>Nombre total de parties jouées et taux de réussite</li><li>Série actuelle et meilleure série</li><li>Bilan par niveau de difficulté : parties gagnées, meilleur temps, temps moyen</li><li>Calendrier du défi quotidien avec indicateurs de réussite</li></ul><p><img src="/screenshot-mac-settings.png" alt="Statistiques de Sudoku sur Mac"></p><h2 id="themes" tabindex="-1">Thèmes <a class="header-anchor" href="#themes" aria-label="Permalink to “Thèmes”">​</a></h2><p>Choisissez parmi huit magnifiques thèmes de couleurs dans les réglages :</p><table tabindex="0"><thead><tr><th>Thème</th><th>Style</th></tr></thead><tbody><tr><td>Classic</td><td>Blanc épuré avec des accents bleus</td></tr><tr><td>Midnight</td><td>Mode sombre aux bleus profonds</td></tr><tr><td>Paper</td><td>Texture chaude de parchemin</td></tr><tr><td>Forest</td><td>Verts naturels</td></tr><tr><td>Ocean</td><td>Bleus marins apaisants</td></tr><tr><td>Sunset</td><td>Dégradés d&#39;orange chaleureux</td></tr><tr><td>Lavender</td><td>Tons violets doux</td></tr><tr><td>Rose</td><td>Élégante palette rose</td></tr></tbody></table><h2 id="synchronisation-icloud" tabindex="-1">Synchronisation iCloud <a class="header-anchor" href="#synchronisation-icloud" aria-label="Permalink to “Synchronisation iCloud”">​</a></h2><p>Lorsque vous êtes connecté à iCloud sur votre appareil :</p><ul><li>Les parties sauvegardées se synchronisent automatiquement — reprenez sur n&#39;importe quel appareil</li><li>Les statistiques et les réglages restent synchronisés</li><li>La progression du défi quotidien est transférée d&#39;un appareil à l&#39;autre</li><li>Nécessite iOS/iPadOS 16 ou version ultérieure, ou macOS 15 ou version ultérieure</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>Connectez Game Center pour :</p><ul><li>Vous mesurer aux autres dans les <strong>classements</strong> des meilleurs temps de résolution par niveau de difficulté</li><li>Débloquer des <strong>succès</strong> : First Solve, Easy/Medium/Hard/Expert/Master Clear, Flawless (sans indice ni erreur)</li></ul><h2 id="imprimer-des-grilles-mac" tabindex="-1">Imprimer des grilles (Mac) <a class="header-anchor" href="#imprimer-des-grilles-mac" aria-label="Permalink to “Imprimer des grilles (Mac)”">​</a></h2><p>Sur Mac, imprimez des grilles directement depuis l&#39;application :</p><ol><li>Ouvrez la boîte de dialogue <strong>Imprimer</strong> depuis la barre d&#39;outils</li><li>Sélectionnez le niveau de difficulté (de Facile à Maître)</li><li>Activez « Inclure les solutions » si vous le souhaitez</li><li>Cliquez sur <strong>Imprimer</strong></li></ol><p>Parfait pour résoudre hors ligne avec un stylo et du papier !</p><h2 id="effets-sonores" tabindex="-1">Effets sonores <a class="header-anchor" href="#effets-sonores" aria-label="Permalink to “Effets sonores”">​</a></h2><p>Sudoku propose des effets sonores discrets :</p><ul><li>Confirmation du placement d&#39;un chiffre</li><li>Révélation d&#39;un indice</li><li>Alerte d&#39;erreur</li><li>Célébration de la victoire</li></ul><p>Activez ou désactivez le son dans <strong>Réglages → Son</strong>.</p><h2 id="astuces-et-conseils" tabindex="-1">Astuces et conseils <a class="header-anchor" href="#astuces-et-conseils" aria-label="Permalink to “Astuces et conseils”">​</a></h2><ul><li><strong>Partez de ce qui est donné</strong> — examinez les lignes, les colonnes et les blocs qui contiennent déjà beaucoup de chiffres.</li><li><strong>Utilisez les notes au crayon</strong> — elles sont particulièrement utiles aux niveaux Difficile, Expert et Maître.</li><li><strong>Cherchez les célibataires nus</strong> — si une case ne peut contenir qu&#39;un seul candidat, remplissez-la.</li><li><strong>Cherchez les célibataires cachés</strong> — si un chiffre ne peut aller qu&#39;à un seul endroit dans une ligne, une colonne ou un bloc, placez-le à cet endroit.</li><li><strong>Usez des indices avec parcimonie</strong> — ils sont excellents pour apprendre, mais terminer une grille sans indice procure plus de satisfaction.</li><li><strong>Entretenez votre série quotidienne</strong> — le défi quotidien est un excellent moyen de s&#39;entraîner régulièrement.</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};